  ('lsec-eng-002', 1, 'in_review', array['lower_secondary']::text[], 'english', 'Usage', 'Their / there / they''re', 2, 'apply', 'mcq', 'Choose the correct word: ___ going to the library after school.', '[{"id":"a","text":"Their"},{"id":"b","text":"There"},{"id":"c","text":"They''re"},{"id":"d","text":"Theyre"}]'::jsonb, null, 'Use commonly confused homophones correctly.', 'Lower secondary English: spelling and usage (e.g. KSSM Bahasa Inggeris).', 'Eduventure (original questions)', 'CC BY 4.0'),
  ('lsec-eng-003', 1, 'in_review', array['lower_secondary']::text[], 'english', 'Vocabulary', 'Antonyms', 2, 'understand', 'mcq', 'Which word is the opposite of "generous"?', '[{"id":"a","text":"kind"},{"id":"b","text":"selfish"},{"id":"c","text":"wealthy"},{"id":"d","text":"honest"}]'::jsonb, null, 'Recognise antonyms.', 'Lower secondary English: vocabulary (e.g. KSSM Bahasa Inggeris).', 'Eduventure (original questions)', 'CC BY 4.0'),
  ('lsec-eng-004', 1, 'in_review', array['lower_secondary']::text[], 'english', 'Punctuation', 'Commas in lists', 3, 'analyze', 'mcq', 'Which sentence uses commas correctly?', '[{"id":"a","text":"I bought apples, bananas and oranges."},{"id":"b","text":"I bought, apples bananas and oranges."},{"id":"c","text":"I bought apples bananas, and, oranges."},{"id":"d","text":"I, bought apples bananas and oranges."}]'::jsonb, null, 'Use commas to separate items in a list.', 'Lower secondary English: punctuation (e.g. KSSM Bahasa Inggeris).', 'Eduventure (original questions)', 'CC BY 4.0'),
  ('lsec-eng-005', 1, 'in_review', array['lower_secondary']::text[], 'english', 'Vocabulary', 'Idioms', 2, 'understand', 'mcq', 'What does the idiom "break the ice" mean?', '[{"id":"a","text":"To start a conversation and make people feel relaxed"},{"id":"b","text":"To damage something cold"},{"id":"c","text":"To end a friendship"},{"id":"d","text":"To win a competition easily"}]'::jsonb, null, 'Interpret common idioms.', 'Lower secondary English: vocabulary – idioms (e.g. KSSM Bahasa Inggeris).', 'Eduventure (original questions)', 'CC BY 4.0'),
  ('gen-001', 1, 'in_review', array['early_childhood','primary','lower_secondary','upper_secondary','pre_university','diploma','undergraduate','postgraduate','doctoral','vocational','lifelong']::text[], 'general_knowledge', 'Geography', 'Continents', 1, 'remember', 'numeric', 'How many continents are there on Earth (using the most common way of counting)?', null, null, 'Name the world''s continents.', 'General knowledge: world geography.', 'Eduventure (original questions)', 'CC BY 4.0'),
  ('gen-002', 1, 'in_review', array['early_childhood','primary','lower_secondary','upper_secondary','pre_university','diploma','undergraduate','postgraduate','doctoral','vocational','lifelong']::text[], 'general_knowledge', 'Geography', 'Oceans', 1, 'remember', 'mcq', 'Which is the largest ocean on Earth?', '[{"id":"a","text":"Atlantic Ocean"},{"id":"b","text":"Indian Ocean"},{"id":"c","text":"Pacific Ocean"},{"id":"d","text":"Arctic Ocean"}]'::jsonb, null, 'Identify the world''s oceans.', 'General knowledge: world geography.', 'Eduventure (original questions)', 'CC BY 4.0'),
  ('gen-003', 1, 'in_review', array['early_childhood','primary','lower_secondary','upper_secondary','pre_university','diploma','undergraduate','postgraduate','doctoral','vocational','lifelong']::text[], 'general_knowledge', 'Space', 'Planets', 1, 'remember', 'mcq', 'Which planet is known as the Red Planet?', '[{"id":"a","text":"Jupiter"},{"id":"b","text":"Mars"},{"id":"c","text":"Venus"},{"id":"d","text":"Saturn"}]'::jsonb, null, 'Recall features of the planets.', 'General knowledge: space.', 'Eduventure (original questions)', 'CC BY 4.0'),
  ('gen-004', 1, 'in_review', array['early_childhood','primary','lower_secondary','upper_secondary','pre_university','diploma','undergraduate','postgraduate','doctoral','vocational','lifelong']::text[], 'general_knowledge', 'Calendar', 'Leap years', 1, 'remember', 'numeric', 'How many days are there in a leap year?', null, 'days', 'Know the length of years in the calendar.', 'General knowledge: time and calendars.', 'Eduventure (original questions)', 'CC BY 4.0'),
  ('gen-005', 1, 'in_review', array['early_childhood','primary','lower_secondary','upper_secondary','pre_university','diploma','undergraduate','postgraduate','doctoral','vocational','lifelong']::text[], 'general_knowledge', 'Geography', 'Capital cities', 2, 'remember', 'mcq', 'What is the capital city of Malaysia?', '[{"id":"a","text":"Kuala Lumpur"},{"id":"b","text":"Putrajaya"},{"id":"c","text":"Johor Bahru"},{"id":"d","text":"George Town"}]'::jsonb, null, 'Recall capital cities.', 'General knowledge: geography of Malaysia.', 'Eduventure (original questions)', 'CC BY 4.0'),
  ('gen-006', 1, 'in_review', array['early_childhood','primary','lower_secondary','upper_secondary','pre_university','diploma','undergraduate','postgraduate','doctoral','vocational','lifelong']::text[], 'general_knowledge', 'Chemistry', 'Common formulas', 1, 'remember', 'mcq', 'What is the chemical formula for water?', '[{"id":"a","text":"CO₂"},{"id":"b","text":"H₂O"},{"id":"c","text":"O₂"},{"id":"d","text":"NaCl"}]'::jsonb, null, 'Recognise common chemical formulas.', 'General knowledge: science.', 'Eduventure (original questions)', 'CC BY 4.0'),
  ('gen-007', 1, 'in_review', array['early_childhood','primary','lower_secondary','upper_secondary','pre_university','diploma','undergraduate','postgraduate','doctoral','vocational','lifelong']::text[], 'general_knowledge', 'Myths and facts', 'Landmarks from space', 3, 'evaluate', 'true_false', 'True or false: the Great Wall of China can be seen from the Moon with the naked eye.', null, null, 'Evaluate common claims using evidence.', 'General knowledge: critical thinking.', 'Eduventure (original questions)', 'CC BY 4.0'),
  ('gen-008', 1, 'in_review', array['early_childhood','primary','lower_secondary','upper_secondary','pre_university','diploma','undergraduate','postgraduate','doctoral','vocational','lifelong']::text[], 'general_knowledge', 'History of science', 'Evolution', 2, 'remember', 'mcq', 'Which scientist is best known for the theory of evolution by natural selection?', '[{"id":"a","text":"Isaac Newton"},{"id":"b","text":"Charles Darwin"},{"id":"c","text":"Marie Curie"},{"id":"d","text":"Albert Einstein"}]'::jsonb, null, 'Recall key scientists and their contributions.', 'General knowledge: history of science.', 'Eduventure (original questions)', 'CC BY 4.0'),
  ('gen-009', 1, 'in_review', array['early_childhood','primary','lower_secondary','upper_secondary','pre_university','diploma','undergraduate','postgraduate','doctoral','vocational','lifelong']::text[], 'general_knowledge', 'Time', 'Converting hours to minutes', 1, 'apply', 'numeric', 'How many minutes are there in 3 hours?', null, 'minutes', 'Convert between units of time.', 'General knowledge: time.', 'Eduventure (original questions)', 'CC BY 4.0'),
  ('gen-010', 1, 'in_review', array['early_childhood','primary','lower_secondary','upper_secondary','pre_university','diploma','undergraduate','postgraduate','doctoral','vocational','lifelong']::text[], 'general_knowledge', 'Science tools', 'Measuring instruments', 1, 'remember', 'mcq', 'Which instrument is used to measure temperature?', '[{"id":"a","text":"Thermometer"},{"id":"b","text":"Barometer"},{"id":"c","text":"Ruler"},{"id":"d","text":"Stopwatch"}]'::jsonb, null, 'Match measuring instruments to quantities.', 'General knowledge: science.', 'Eduventure (original questions)', 'CC BY 4.0')
insert into public.question_keys (question_id, answer, explanation, wrong, mistakes) values
  ('pri-math-001', '"b"'::jsonb, '7 × 8 = 56. A quick check: 7 × 4 = 28, and doubling gives 56.', '{"a":"54 is 6 × 9 (or 9 × 6), not 7 × 8.","c":"58 is not in the 7 or 8 times table; 7 × 8 is two less.","d":"63 is 7 × 9, which is one group of 7 too many."}'::jsonb, null),
  ('pri-math-002', '{"value":83,"tolerance":0}'::jsonb, 'Add the ones: 5 + 8 = 13, write 3 and carry 1 ten. Add the tens: 4 + 3 + 1 = 8. So 45 + 38 = 83.', null, '[{"value":73,"why":"73 forgets the ten that was carried from 5 + 8 = 13."}]'::jsonb),
  ('pri-math-003', '{"value":53,"tolerance":0}'::jsonb, 'Count up from 47: 47 + 3 = 50, then 50 + 50 = 100. That is 3 + 50 = 53.', null, '[{"value":63,"why":"63 + 47 = 110, so 63 is ten too many."},{"value":47,"why":"47 is the number being taken away, not what is left."}]'::jsonb),
  ('pri-math-004', '"b"'::jsonb, 'As decimals: 3/4 = 0.75, 2/3 ≈ 0.67, 3/5 = 0.6 and 1/2 = 0.5. So 3/4 is the largest.', '{"a":"2/3 is about 0.67, a little less than 3/4 = 0.75.","c":"3/5 = 0.6. Fifths are smaller pieces than quarters.","d":"1/2 = 0.5, the smallest of these."}'::jsonb, null),
  ('pri-math-005', '{"value":9,"tolerance":0}'::jsonb, 'One half means dividing into 2 equal parts: 18 ÷ 2 = 9.', null, '[{"value":36,"why":"36 is double 18, not half of it."}]'::jsonb),
  ('pri-math-006', '"b"'::jsonb, '"Hex" means six, so a hexagon has 6 sides. Honeycomb cells are hexagons.', '{"a":"A 5-sided shape is a pentagon.","c":"A 7-sided shape is a heptagon.","d":"An 8-sided shape is an octagon, like many stop signs."}'::jsonb, null),
  ('pri-math-007', '{"value":16,"tolerance":0,"unit":"cm"}'::jsonb, 'Perimeter is the distance all the way round: 5 + 3 + 5 + 3 = 16 cm.', null, '[{"value":15,"why":"15 is 5 × 3, the area in square centimetres, not the distance around."},{"value":8,"why":"8 is only one length plus one width; there are two of each."}]'::jsonb),
  ('pri-math-008', '{"value":24,"tolerance":0,"unit":"cm²"}'::jsonb, 'Area of a rectangle = length × width = 6 × 4 = 24 cm².', null, '[{"value":20,"why":"20 is the perimeter (6 + 4 + 6 + 4), not the area."}]'::jsonb),
  ('pri-math-009', '"c"'::jsonb, '4,728 = 4 thousands + 7 hundreds + 2 tens + 8 ones. The 7 is in the hundreds place, so it is worth 700.', '{"a":"7 would be the value if the digit were in the ones place.","b":"70 would be the value in the tens place; that digit is 2.","d":"7,000 would be the thousands place; that digit is 4."}'::jsonb, null),
  ('pri-math-010', '{"value":120,"tolerance":0,"unit":"minutes"}'::jsonb, '1 hour = 60 minutes, so 2 hours = 2 × 60 = 120 minutes.', null, '[{"value":200,"why":"There are 60 minutes in an hour, not 100."}]'::jsonb),
  ('pri-math-011', '{"value":7,"tolerance":0}'::jsonb, 'Division undoes multiplication: 7 × 8 = 56, so 56 ÷ 8 = 7.', null, '[{"value":8,"why":"8 is the number you divide by; 8 × 8 = 64, not 56."}]'::jsonb),
  ('pri-math-012', '{"value":1.6,"tolerance":0.001,"unit":"RM"}'::jsonb, 'RM5.00 − RM3.40 = RM1.60. Count up: RM3.40 + RM0.60 = RM4, then + RM1 = RM5.', null, '[{"value":2.6,"why":"RM2.60 + RM3.40 = RM6, so that is one ringgit too much."}]'::jsonb),
  ('pri-math-013', '"b"'::jsonb, '347 lies between 340 and 350. The ones digit is 7 (5 or more), so round up to 350.', '{"a":"340 is rounding down, but a ones digit of 7 means we round up.","c":"300 is 347 rounded to the nearest hundred, not the nearest ten.","d":"400 is not a nearest ten of 347; it is 53 away."}'::jsonb, null),
  ('pri-math-014', '{"value":0.75,"tolerance":0.0001}'::jsonb, 'Line up the decimal points: 0.50 + 0.25 = 0.75. (Half plus a quarter is three quarters.)', null, '[{"value":0.3,"why":"0.30 comes from adding 5 + 25 as if they were the same place value; write 0.5 as 0.50 first."}]'::jsonb),
  ('pri-math-015', '"true"'::jsonb, 'A rectangle is any four-sided shape with four right angles. A square has four right angles too (and also four equal sides), so every square is a special kind of rectangle.', '{"false":"A square has all the properties of a rectangle: four sides and four right angles. Equal sides are an extra property, not a missing one."}'::jsonb, null),
  ('pri-sci-001', '{"accept":["photosynthesis"]}'::jsonb, 'Photosynthesis: "photo" means light and "synthesis" means making. Plants use light energy to make sugar and release oxygen.', null, null),
  ('pri-sci-002', '"a"'::jsonb, 'Dolphins are mammals: they breathe air with lungs, are warm-blooded and feed their young with milk.', '{"b":"Sharks are fish. They breathe through gills.","c":"Turtles are reptiles. They lay eggs with leathery shells.","d":"Octopuses are molluscs, related to snails and squid."}'::jsonb, null),
  ('pri-sci-003', '"c"'::jsonb, 'The order from the Sun begins Mercury, Venus, Earth, Mars. Mercury is closest.', '{"a":"Venus is second from the Sun. It is the hottest planet, but not the closest.","b":"Earth is third from the Sun.","d":"Mars is fourth from the Sun."}'::jsonb, null),
  ('pri-sci-004', '{"value":100,"tolerance":0,"unit":"°C"}'::jsonb, 'Pure water boils at 100 °C at sea level, and freezes at 0 °C.', null, '[{"value":0,"why":"0 °C is the freezing point of water, not the boiling point."}]'::jsonb),
  ('pri-sci-005', '"b"'::jsonb, 'The heart is a muscle that pumps blood through blood vessels to every part of the body.', '{"a":"The lungs take in oxygen and remove carbon dioxide, but they do not pump blood.","c":"The stomach helps digest food.","d":"The brain controls the body, but the heart does the pumping."}'::jsonb, null),
  ('pri-sci-006', '"false"'::jsonb, 'Sound is a vibration passed from particle to particle. Empty space has no particles to vibrate, so sound cannot travel there. That is why space is silent.', '{"true":"Sound needs a material (solid, liquid or gas) to travel through. In a vacuum there is nothing to carry the vibrations."}'::jsonb, null),
  ('pri-sci-007', '"a"'::jsonb, 'Melting is the change from solid to liquid. Ice melts into liquid water.', '{"b":"Changing into a gas is called evaporation or boiling, which happens after melting when water is heated more.","c":"Melting makes a material softer and runny, not harder.","d":"Melting is a physical change: it is still water, just in a different state."}'::jsonb, null),
  ('pri-sci-008', '"c"'::jsonb, 'Metals such as copper let electricity flow easily. That is why electrical wires are made of copper.', '{"a":"Dry wood is an insulator: it does not let electricity flow easily.","b":"Plastic is an insulator, which is why it covers electrical wires.","d":"Rubber is an insulator, used to keep people safe from electric shocks."}'::jsonb, null),
  ('pri-sci-009', '"a"'::jsonb, 'A tadpole grows legs and loses its tail, becoming a froglet before it is a fully grown frog.', '{"b":"A caterpillar is a stage in a butterfly''s life cycle.","c":"A pupa is a stage for insects such as butterflies, not frogs.","d":"Frogs are amphibians, not fish, and there is no ''larva fish'' stage."}'::jsonb, null),
  ('pri-sci-010', '"a"'::jsonb, 'Light travels in straight lines. When an opaque object blocks it, a dark area forms behind the object: a shadow.', '{"b":"A mirror bounces light back (reflection); it does not create a shadow by itself.","c":"Light can warm things up, but that is not what makes a shadow.","d":"Brighter light makes shadows sharper, but the shadow itself comes from light being blocked."}'::jsonb, null),
  ('pri-eng-001', '"b"'::jsonb, '"Child" has an irregular plural: one child, two children.', '{"a":"Adding -s works for most nouns, but not for \"child\".","c":"Adding -es is used after s, x, ch or sh endings (box → boxes), not for \"child\".","d":"\"Children\" is already plural, so it does not take another -s."}'::jsonb, null),
  ('pri-eng-002', '"c"'::jsonb, '"Go" is irregular: go → went → gone. For a simple past action we use "went".', '{"a":"\"Goed\" is not a word; \"go\" does not follow the -ed rule.","b":"\"Gone\" needs a helper verb: \"I have gone\".","d":"\"Going\" describes an action in progress: \"I was going\"."}'::jsonb, null),
  ('pri-eng-003', '"a"'::jsonb, 'An adjective describes a noun. "Tall" describes the girl.', '{"b":"\"Girl\" is a noun: it names a person.","c":"\"Ran\" is a verb: it is the action.","d":"\"Quickly\" is an adverb: it describes how she ran."}'::jsonb, null),
  ('pri-eng-004', '"b"'::jsonb, '"Joyful" means full of joy, which is very close in meaning to "happy". Words with similar meanings are synonyms.', '{"a":"\"Angry\" is a different feeling, closer to an opposite of happy.","c":"\"Tired\" means needing rest; it is not about happiness.","d":"\"Nervous\" means worried or anxious."}'::jsonb, null),
  ('pri-eng-005', '"b"'::jsonb, 'For a habit in the present simple, he/she/it takes -s: she walks.', '{"a":"\"Walk\" goes with I, you, we and they, not she.","c":"\"Walking\" needs a helper verb such as \"is\".","d":"\"Are\" goes with you, we or they; and \"every day\" calls for the present simple."}'::jsonb, null),
  ('lsec-math-001', '{"value":6,"tolerance":0}'::jsonb, 'Subtract 5 from both sides: 2x = 12. Divide both sides by 2: x = 6. Check: 2 × 6 + 5 = 17.', null, '[{"value":11,"why":"11 comes from 17 − 5 − 1 or similar; first subtract 5 (giving 12), then divide by 2."},{"value":12,"why":"12 is 2x, not x. Divide by 2 as the last step."}]'::jsonb),
  ('lsec-math-002', '"a"'::jsonb, 'Expand: 3(x + 4) = 3x + 12. Then 3x + 12 − 2x = x + 12.', '{"b":"Multiply both terms inside the brackets by 3: 3 × 4 = 12, not 4.","c":"Subtracting 2x lowers 3x to x; adding would give 5x.","d":"3 × 4 is 12, not 3 + 4 = 7."}'::jsonb, null),
  ('lsec-math-003', '{"value":5,"tolerance":0}'::jsonb, 'Start at −7 on a number line and move 12 to the right: you pass 0 after 7 steps and have 5 more, landing on 5.', null, '[{"value":-19,"why":"−19 treats the 12 as negative too; adding a positive number moves right."},{"value":-5,"why":"The positive number (12) is bigger than 7, so the answer is positive."}]'::jsonb),
  ('lsec-math-004', '{"value":12,"tolerance":0}'::jsonb, 'A negative times a negative is positive: (−3) × (−4) = 12.', null, '[{"value":-12,"why":"Two negative signs multiply to give a positive result."},{"value":-7,"why":"−7 is what you get by adding −3 and −4, not multiplying."}]'::jsonb),
  ('lsec-math-005', '{"value":12,"tolerance":0}'::jsonb, '10% of 80 is 8 and 5% is half of that, 4. So 15% = 8 + 4 = 12.', null, '[{"value":65,"why":"65 is 80 − 15; a percentage is a fraction of 80, not a subtraction."}]'::jsonb),
  ('lsec-math-006', '"a"'::jsonb, 'The highest common factor of 12 and 18 is 6. 12 ÷ 6 = 2 and 18 ÷ 6 = 3, giving 2 : 3.', '{"b":"The order matters: 12 comes first, so it is 2 : 3, not 3 : 2.","c":"4 : 6 is equal, but both can still be divided by 2.","d":"6 : 9 is equal, but both can still be divided by 3."}'::jsonb, null),
  ('lsec-math-007', '{"value":70,"tolerance":0,"unit":"°"}'::jsonb, 'The angles of a triangle add up to 180°. 180 − 50 − 60 = 70°.', null, '[{"value":250,"why":"250 uses 360°, which is the angle sum of a quadrilateral, not a triangle."}]'::jsonb),
  ('lsec-math-008', '{"value":154,"tolerance":0,"unit":"cm²"}'::jsonb, 'Area = πr² = 22/7 × 7 × 7 = 22 × 7 = 154 cm².', null, '[{"value":44,"why":"44 cm is the circumference (2πr), not the area."},{"value":22,"why":"22 is π × r using only one 7; the radius must be squared."}]'::jsonb),
  ('lsec-math-009', '{"value":10,"tolerance":0,"unit":"cm"}'::jsonb, 'c² = a² + b² = 36 + 64 = 100, so c = √100 = 10 cm.', null, '[{"value":14,"why":"14 adds the sides directly; Pythagoras adds their squares, then takes the square root."},{"value":100,"why":"100 is c², not c. Take the square root at the end."}]'::jsonb),
  ('lsec-math-010', '{"value":7,"tolerance":0}'::jsonb, 'Add them: 4 + 8 + 6 + 10 + 7 = 35. There are 5 numbers, so the mean is 35 ÷ 5 = 7.', null, '[{"value":35,"why":"35 is the total; divide by how many numbers there are (5)."},{"value":6,"why":"6 is the middle value when the list is unsorted; the mean uses the total."}]'::jsonb),
  ('lsec-math-011', '{"value":12,"tolerance":0}'::jsonb, '12 × 12 = 144, so √144 = 12.', null, '[{"value":72,"why":"72 is half of 144; a square root is the number that multiplies by itself to make 144."}]'::jsonb),
  ('lsec-math-012', '{"value":32,"tolerance":0}'::jsonb, '2⁵ = 2 × 2 × 2 × 2 × 2 = 32.', null, '[{"value":10,"why":"10 is 2 × 5; a power means multiplying 2 by itself 5 times."},{"value":25,"why":"25 is 5², which swaps the base and the power."}]'::jsonb),
  ('lsec-math-013', '"a"'::jsonb, 'Multiply each term by each term: x·x + x·2 + 3·x + 3·2 = x² + 2x + 3x + 6 = x² + 5x + 6.', '{"b":"This misses the middle terms 2x and 3x.","c":"The numbers are swapped: add 3 + 2 for the x term and multiply 3 × 2 for the constant.","d":"This adds the brackets instead of multiplying them."}'::jsonb, null),
  ('lsec-math-014', '{"value":3,"tolerance":0}'::jsonb, 'Gradient = change in y ÷ change in x = (8 − 2) ÷ (3 − 1) = 6 ÷ 2 = 3.', null, '[{"value":0.3333,"why":"That is change in x ÷ change in y; the gradient is rise over run (y over x)."},{"value":6,"why":"6 is the change in y only; divide by the change in x (2)."}]'::jsonb),
  ('lsec-math-015', '"false"'::jsonb, '2 is a prime number (its only factors are 1 and 2) and it is even. It is the only even prime.', '{"true":"One counter-example is enough to make a rule false: 2 is prime and even."}'::jsonb, null),
  ('lsec-sci-001', '{"accept":["cell","cells"]}'::jsonb, 'All living things are made of one or more cells. Cells are the smallest unit that can carry out life processes.', null, null),
  ('lsec-sci-002', '"c"'::jsonb, 'Sodium''s symbol Na comes from its Latin name, natrium.', '{"a":"\"So\" is not a chemical symbol.","b":"\"Sd\" is not a chemical symbol.","d":"S is the symbol for sulfur."}'::jsonb, null),
  ('lsec-sci-003', '{"value":7,"tolerance":0}'::jsonb, 'Pure water is neutral, with a pH of 7 at 25 °C. Below 7 is acidic, above 7 is alkaline.', null, '[{"value":0,"why":"pH 0 is extremely acidic; pure water is neutral."},{"value":14,"why":"pH 14 is extremely alkaline; pure water is neutral (7)."}]'::jsonb),
  ('lsec-sci-004', '"b"'::jsonb, 'Photosynthesis uses carbon dioxide and water to make glucose, and releases oxygen as a by-product.', '{"a":"Carbon dioxide is taken in during photosynthesis, not released.","c":"Nitrogen is the main gas in air, but it is not made by photosynthesis.","d":"Hydrogen is not released by plants during photosynthesis."}'::jsonb, null),
  ('lsec-sci-005', '{"value":5,"tolerance":0,"unit":"m/s"}'::jsonb, 'Speed = distance ÷ time = 100 m ÷ 20 s = 5 m/s.', null, '[{"value":2000,"why":"2000 multiplies distance by time; speed divides distance by time."},{"value":0.2,"why":"0.2 is time ÷ distance; it should be distance ÷ time."}]'::jsonb),
  ('lsec-sci-006', '"b"'::jsonb, 'Mitochondria release energy from glucose through aerobic respiration, which is why they are called the cell''s powerhouses.', '{"a":"The nucleus holds genetic material and controls the cell.","c":"The cell wall (in plants) gives support and shape.","d":"The vacuole stores water and dissolved substances."}'::jsonb, null),
  ('lsec-sci-007', '"c"'::jsonb, 'Force is measured in newtons (N), named after Isaac Newton.', '{"a":"The joule (J) is the unit of energy and work.","b":"The watt (W) is the unit of power.","d":"The pascal (Pa) is the unit of pressure."}'::jsonb, null),
  ('lsec-sci-008', '"false"'::jsonb, 'Mass is the amount of matter and stays the same everywhere. Weight is the pull of gravity on that mass, so the astronaut weighs less on the Moon but has the same mass.', '{"true":"It is weight that changes, because the Moon''s gravity is weaker. The amount of matter (mass) stays the same."}'::jsonb, null),
  ('lsec-sci-009', '"b"'::jsonb, 'Solar energy comes from the Sun and will not run out on human timescales, so it is renewable.', '{"a":"Coal is a fossil fuel; it takes millions of years to form, so it is non-renewable.","c":"Natural gas is a fossil fuel and non-renewable.","d":"Petroleum (crude oil) is a fossil fuel and non-renewable."}'::jsonb, null),
  ('lsec-sci-010', '"a"'::jsonb, 'Water is made of hydrogen and oxygen chemically joined in a fixed ratio, so it is a compound.', '{"b":"An element contains only one kind of atom; water has two (hydrogen and oxygen).","c":"In a mixture the parts are not chemically joined and can vary; water''s ratio is fixed.","d":"Water is not a metal."}'::jsonb, null),
  ('lsec-eng-001', '"b"'::jsonb, 'In the passive voice, the thing receiving the action becomes the subject: "The meal was cooked (by the chef)". It uses be + past participle.', '{"a":"This is active voice: the chef (the doer) is the subject.","c":"This is active voice in the present continuous tense.","d":"This is an imperative (a command)."}'::jsonb, null),
  ('lsec-eng-002', '"c"'::jsonb, '"They''re" is short for "they are": They are going to the library.', '{"a":"\"Their\" shows belonging: their books.","b":"\"There\" refers to a place: over there.","d":"The contraction needs an apostrophe: they''re."}'::jsonb, null),
  ('lsec-eng-003', '"b"'::jsonb, 'A generous person happily gives to others; a selfish person thinks mainly of themselves. They are antonyms.', '{"a":"\"Kind\" is close in meaning to generous, not opposite.","c":"\"Wealthy\" means rich; a wealthy person can be generous or not.","d":"\"Honest\" means truthful; it is unrelated to giving."}'::jsonb, null),
  ('lsec-eng-004', '"a"'::jsonb, 'Commas separate items in a list: apples, bananas and oranges. (A comma before "and" — the Oxford comma — is also acceptable in many styles.)', '{"b":"There should be no comma between the verb \"bought\" and its object.","c":"\"Apples\" and \"bananas\" need a comma between them, and \"and\" should not be surrounded by commas.","d":"A comma should not separate the subject \"I\" from its verb."}'::jsonb, null),
  ('lsec-eng-005', '"a"'::jsonb, '"Break the ice" means doing or saying something to ease tension when people first meet, such as asking a friendly question.', '{"b":"That is the literal meaning; an idiom has a figurative meaning.","c":"Ending a friendship is not what this idiom means.","d":"Winning easily is described by idioms such as \"a piece of cake\"."}'::jsonb, null),
  ('gen-001', '{"value":7,"tolerance":0}'::jsonb, 'The most widely taught model has 7 continents: Africa, Antarctica, Asia, Australia (Oceania), Europe, North America and South America. Some countries teach 5 or 6 by combining some of them.', null, '[{"value":5,"why":"Some models combine continents (e.g. the Americas), but the most common count is 7."}]'::jsonb),
  ('gen-002', '"c"'::jsonb, 'The Pacific Ocean is the largest and deepest ocean, covering about a third of Earth''s surface.', '{"a":"The Atlantic is the second largest.","b":"The Indian Ocean is the third largest.","d":"The Arctic is the smallest of the major oceans."}'::jsonb, null),
  ('gen-003', '"b"'::jsonb, 'Mars looks red because its surface contains a lot of iron oxide (rust).', '{"a":"Jupiter is the largest planet, with a famous Great Red Spot, but it is not called the Red Planet.","c":"Venus looks bright white-yellow because of its thick clouds.","d":"Saturn is known for its rings."}'::jsonb, null),
  ('gen-004', '{"value":366,"tolerance":0,"unit":"days"}'::jsonb, 'A leap year has 366 days: February gets an extra day, the 29th.', null, '[{"value":365,"why":"365 is an ordinary year; a leap year adds 29 February."}]'::jsonb),
  ('gen-005', '"a"'::jsonb, 'Kuala Lumpur is Malaysia''s capital city. Many government offices moved to Putrajaya, which is the federal administrative centre.', '{"b":"Putrajaya is the federal administrative centre, where many ministries are, but Kuala Lumpur is the capital.","c":"Johor Bahru is the capital of the state of Johor.","d":"George Town is the capital of the state of Penang."}'::jsonb, null),
  ('gen-006', '"b"'::jsonb, 'Each water molecule has two hydrogen atoms and one oxygen atom: H₂O.', '{"a":"CO₂ is carbon dioxide.","c":"O₂ is oxygen gas.","d":"NaCl is sodium chloride, ordinary table salt."}'::jsonb, null),
  ('gen-007', '"false"'::jsonb, 'The wall is long but only a few metres wide, far too narrow to see from the Moon, about 384,000 km away. Astronauts have confirmed this.', '{"true":"This is a popular myth. From the Moon even whole countries are hard to make out; a wall a few metres wide is invisible."}'::jsonb, null),
  ('gen-008', '"b"'::jsonb, 'Charles Darwin published "On the Origin of Species" in 1859. Alfred Russel Wallace reached similar ideas at the same time.', '{"a":"Newton is known for the laws of motion and gravity.","c":"Marie Curie is known for her research on radioactivity.","d":"Einstein is known for the theory of relativity."}'::jsonb, null),
  ('gen-009', '{"value":180,"tolerance":0,"unit":"minutes"}'::jsonb, 'Each hour has 60 minutes: 3 × 60 = 180 minutes.', null, '[{"value":300,"why":"There are 60 minutes in an hour, not 100."}]'::jsonb),
  ('gen-010', '"a"'::jsonb, 'A thermometer measures temperature. "Thermo" relates to heat.', '{"b":"A barometer measures air pressure.","c":"A ruler measures length.","d":"A stopwatch measures time."}'::jsonb, null)
